/*
 * arc-wasm: the "audio" service (IAudioService) in lean form, for
 * AudioManager: stream volumes (applied to the in-process mixer through
 * AudioSystem.setStreamVolumeIndex, shim/audio), mute, ringer mode, audio
 * mode, audio focus. One output (the page's Web Audio); no speakerphone,
 * Bluetooth, remote controls, sound effects or ringtone player. Methods not
 * overridden here throw (AudioServiceBase, generated by
 * tools/gen_binder_base.py). Registered at VM start with the audio natives
 * (shim/audio/register_audio.cc), only if no "audio" service exists yet.
 * Topic gles-audio, docs/topics/gles-audio.md.
 */
package arcwasm.server;

import android.content.Context;
import android.media.AudioManager;
import android.media.AudioRoutesInfo;
import android.media.AudioSystem;
import android.media.IAudioFocusDispatcher;
import android.media.IAudioRoutesObserver;
import android.os.IBinder;
import android.os.RemoteException;
import android.os.ServiceManager;
import android.util.Log;

import arcwasm.server.base.AudioServiceBase;

import java.util.ArrayList;

public final class AudioService extends AudioServiceBase {
    private static final String TAG = "AudioService";

    // AudioService.MAX_STREAM_VOLUME and AudioManager.DEFAULT_STREAM_VOLUME
    // (AOSP 4.4), by stream type.
    private static final int[] MAX_STREAM_VOLUME = {5, 7, 7, 15, 7, 7, 15, 7, 15, 15};
    private static final int[] DEFAULT_STREAM_VOLUME = {4, 7, 5, 11, 6, 5, 7, 7, 11, 11};

    private static AudioService sInstance;

    private final Object mLock = new Object();
    private final int[] mIndex = new int[AudioSystem.getNumStreamTypes()];
    private final boolean[] mMuted = new boolean[AudioSystem.getNumStreamTypes()];
    private boolean mMasterMute;
    private int mRingerMode = AudioManager.RINGER_MODE_NORMAL;
    private int mMode = AudioSystem.MODE_NORMAL;
    private boolean mSpeakerphoneOn;
    private final int[] mVibrateSetting = new int[2];

    private static final class FocusRequest {
        final IAudioFocusDispatcher dispatcher;
        final String clientId;
        final int durationHint;

        FocusRequest(IAudioFocusDispatcher d, String id, int hint) {
            dispatcher = d;
            clientId = id;
            durationHint = hint;
        }
    }

    /** The audio focus stack, top last (MediaFocusControl's). */
    private final ArrayList<FocusRequest> mFocusStack = new ArrayList<FocusRequest>();

    private AudioService() {
        for (int s = 0; s < mIndex.length; s++) {
            mIndex[s] = DEFAULT_STREAM_VOLUME[s];
            AudioSystem.initStreamVolume(s, 0, MAX_STREAM_VOLUME[s]);
            AudioSystem.setStreamVolumeIndex(s, mIndex[s], AudioSystem.DEVICE_OUT_DEFAULT);
        }
    }

    /** Publishes "audio" unless there is one; idempotent. */
    public static synchronized void start() {
        if (sInstance != null || ServiceManager.checkService(Context.AUDIO_SERVICE) != null) {
            return;
        }
        sInstance = new AudioService();
        ServiceManager.addService(Context.AUDIO_SERVICE, sInstance);
    }

    public static AudioService getInstance() {
        return sInstance;
    }

    private static int clampStream(int stream) {
        return stream >= 0 && stream < MAX_STREAM_VOLUME.length ? stream : AudioManager.STREAM_MUSIC;
    }

    private void applyLocked(int stream) {
        int index = mMuted[stream] || mMasterMute ? 0 : mIndex[stream];
        AudioSystem.setStreamVolumeIndex(stream, index, AudioSystem.DEVICE_OUT_DEFAULT);
    }

    // --- volume --------------------------------------------------------------------

    @Override
    public void setStreamVolume(int streamType, int index, int flags, String callingPackage) {
        int s = clampStream(streamType);
        synchronized (mLock) {
            mIndex[s] = Math.max(0, Math.min(index, MAX_STREAM_VOLUME[s]));
            applyLocked(s);
        }
    }

    @Override
    public void adjustStreamVolume(int streamType, int direction, int flags, String callingPackage) {
        int s = clampStream(streamType);
        synchronized (mLock) {
            setStreamVolume(s, mIndex[s] + Integer.signum(direction), flags, callingPackage);
        }
    }

    @Override
    public void adjustVolume(int direction, int flags, String callingPackage) {
        adjustStreamVolume(AudioManager.STREAM_MUSIC, direction, flags, callingPackage);
    }

    @Override
    public void adjustSuggestedStreamVolume(int direction, int suggestedStreamType, int flags,
            String callingPackage) {
        adjustStreamVolume(suggestedStreamType == AudioManager.USE_DEFAULT_STREAM_TYPE
                ? AudioManager.STREAM_MUSIC : suggestedStreamType, direction, flags, callingPackage);
    }

    @Override
    public void adjustLocalOrRemoteStreamVolume(int streamType, int direction, String callingPackage) {
        adjustStreamVolume(streamType, direction, 0, callingPackage);
    }

    @Override
    public int getStreamVolume(int streamType) {
        synchronized (mLock) {
            int s = clampStream(streamType);
            return mMuted[s] ? 0 : mIndex[s];
        }
    }

    @Override
    public int getStreamMaxVolume(int streamType) {
        return MAX_STREAM_VOLUME[clampStream(streamType)];
    }

    @Override
    public int getLastAudibleStreamVolume(int streamType) {
        synchronized (mLock) {
            return mIndex[clampStream(streamType)];
        }
    }

    @Override
    public void setStreamMute(int streamType, boolean state, IBinder cb) {
        int s = clampStream(streamType);
        synchronized (mLock) {
            mMuted[s] = state;
            applyLocked(s);
        }
    }

    @Override
    public void setStreamSolo(int streamType, boolean state, IBinder cb) {
        synchronized (mLock) {
            for (int s = 0; s < mMuted.length; s++) {
                if (s != streamType) {
                    mMuted[s] = state;
                    applyLocked(s);
                }
            }
        }
    }

    @Override
    public boolean isStreamMute(int streamType) {
        synchronized (mLock) {
            return mMuted[clampStream(streamType)];
        }
    }

    @Override
    public void setMasterMute(boolean state, int flags, IBinder cb) {
        synchronized (mLock) {
            mMasterMute = state;
            AudioSystem.setMasterMute(state);
        }
    }

    @Override
    public boolean isMasterMute() {
        synchronized (mLock) {
            return mMasterMute;
        }
    }

    @Override
    public int getMasterVolume() {
        return 0;  // no master volume control (config_useMasterVolume false)
    }

    @Override
    public int getMasterMaxVolume() {
        return 0;
    }

    @Override
    public int getLastAudibleMasterVolume() {
        return 0;
    }

    @Override
    public int getMasterStreamType() {
        return AudioManager.STREAM_MUSIC;  // not voice capable
    }

    @Override
    public void forceVolumeControlStream(int streamType, IBinder cb) {}

    @Override
    public int getRemoteStreamMaxVolume() {
        return 0;
    }

    @Override
    public int getRemoteStreamVolume() {
        return 0;
    }

    @Override
    public boolean isLocalOrRemoteMusicActive() {
        return AudioSystem.isStreamActive(AudioManager.STREAM_MUSIC, 0);
    }

    // --- modes ---------------------------------------------------------------------

    @Override
    public int getRingerMode() {
        synchronized (mLock) {
            return mRingerMode;
        }
    }

    @Override
    public void setRingerMode(int ringerMode) {
        if (AudioManager.isValidRingerMode(ringerMode)) {
            synchronized (mLock) {
                mRingerMode = ringerMode;
            }
        }
    }

    @Override
    public void setVibrateSetting(int vibrateType, int vibrateSetting) {
        if (vibrateType >= 0 && vibrateType < 2) mVibrateSetting[vibrateType] = vibrateSetting;
    }

    @Override
    public int getVibrateSetting(int vibrateType) {
        return vibrateType >= 0 && vibrateType < 2 ? mVibrateSetting[vibrateType] : 0;
    }

    @Override
    public boolean shouldVibrate(int vibrateType) {
        return false;  // no vibrator
    }

    @Override
    public void setMode(int mode, IBinder cb) {
        synchronized (mLock) {
            mMode = mode;
        }
    }

    @Override
    public int getMode() {
        synchronized (mLock) {
            return mMode;
        }
    }

    @Override
    public void setSpeakerphoneOn(boolean on) {
        mSpeakerphoneOn = on;
    }

    @Override
    public boolean isSpeakerphoneOn() {
        return mSpeakerphoneOn;
    }

    @Override
    public void setBluetoothScoOn(boolean on) {}

    @Override
    public boolean isBluetoothScoOn() {
        return false;
    }

    @Override
    public void setBluetoothA2dpOn(boolean on) {}

    @Override
    public boolean isBluetoothA2dpOn() {
        return false;
    }

    @Override
    public boolean isCameraSoundForced() {
        return false;
    }

    @Override
    public AudioRoutesInfo startWatchingRoutes(IAudioRoutesObserver observer) {
        return new AudioRoutesInfo();
    }

    // --- sound effects (none: no decoders for the effect files) ----------------------

    @Override
    public void playSoundEffect(int effectType) {}

    @Override
    public void playSoundEffectVolume(int effectType, float volume) {}

    @Override
    public boolean loadSoundEffects() {
        return false;
    }

    @Override
    public void unloadSoundEffects() {}

    @Override
    public void reloadAudioSettings() {}

    // --- audio focus ---------------------------------------------------------------

    @Override
    public int requestAudioFocus(int mainStreamType, int durationHint, IBinder cb,
            IAudioFocusDispatcher fd, String clientId, String callingPackageName) {
        FocusRequest loser = null;
        synchronized (mLock) {
            removeFocusLocked(clientId);
            if (!mFocusStack.isEmpty()) loser = mFocusStack.get(mFocusStack.size() - 1);
            mFocusStack.add(new FocusRequest(fd, clientId, durationHint));
        }
        if (loser != null && loser.dispatcher != null) {
            // MediaFocusControl: the previous holder loses focus for as long
            // as the new one asked.
            int loss = durationHint == AudioManager.AUDIOFOCUS_GAIN ? AudioManager.AUDIOFOCUS_LOSS
                    : durationHint == AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK
                    ? AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK
                    : AudioManager.AUDIOFOCUS_LOSS_TRANSIENT;
            try {
                loser.dispatcher.dispatchAudioFocusChange(loss, loser.clientId);
            } catch (RemoteException e) {
                Log.w(TAG, "focus loss not delivered", e);
            }
        }
        return AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
    }

    @Override
    public int abandonAudioFocus(IAudioFocusDispatcher fd, String clientId) {
        FocusRequest winner = null;
        synchronized (mLock) {
            boolean wasTop = !mFocusStack.isEmpty()
                    && mFocusStack.get(mFocusStack.size() - 1).clientId.equals(clientId);
            removeFocusLocked(clientId);
            if (wasTop && !mFocusStack.isEmpty()) winner = mFocusStack.get(mFocusStack.size() - 1);
        }
        if (winner != null && winner.dispatcher != null) {
            try {
                winner.dispatcher.dispatchAudioFocusChange(AudioManager.AUDIOFOCUS_GAIN,
                        winner.clientId);
            } catch (RemoteException e) {
                Log.w(TAG, "focus gain not delivered", e);
            }
        }
        return AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
    }

    @Override
    public void unregisterAudioFocusClient(String clientId) {
        synchronized (mLock) {
            removeFocusLocked(clientId);
        }
    }

    @Override
    public int getCurrentAudioFocus() {
        synchronized (mLock) {
            return mFocusStack.isEmpty() ? 0 : mFocusStack.get(mFocusStack.size() - 1).durationHint;
        }
    }

    private void removeFocusLocked(String clientId) {
        for (int i = mFocusStack.size() - 1; i >= 0; i--) {
            if (mFocusStack.get(i).clientId.equals(clientId)) mFocusStack.remove(i);
        }
    }

    // --- media buttons and remote control clients (none) ------------------------------

    @Override
    public void registerMediaButtonIntent(android.app.PendingIntent pi,
            android.content.ComponentName c, IBinder token) {}

    @Override
    public void unregisterMediaButtonIntent(android.app.PendingIntent pi) {}

    @Override
    public int registerRemoteControlClient(android.app.PendingIntent mediaIntent,
            android.media.IRemoteControlClient rcClient, String callingPackageName) {
        return 0;
    }

    @Override
    public void unregisterRemoteControlClient(android.app.PendingIntent mediaIntent,
            android.media.IRemoteControlClient rcClient) {}

    @Override
    public void setPlaybackInfoForRcc(int rccId, int what, int value) {}

    @Override
    public void setPlaybackStateForRcc(int rccId, int state, long timeMs, float speed) {}

    // SystemUI's RingtonePlayer registers here; apps ask for it to play
    // notification sounds (topic userspace). Kept and handed back.
    private android.media.IRingtonePlayer mRingtonePlayer;

    @Override
    public synchronized void setRingtonePlayer(android.media.IRingtonePlayer player) {
        mRingtonePlayer = player;
    }

    @Override
    public synchronized android.media.IRingtonePlayer getRingtonePlayer() {
        return mRingtonePlayer;
    }
}
